"""Hookline webhook relay."""
import json
import settings_loader


def handle_event(payload):
    event = json.loads(payload)
    if event.get("type") != "payment.captured":
        return "skipped"
    conf = settings_loader.load()
    return forward(event, retries=conf["retry_limit"])


def forward(event, retries):
    # posts to the billing service over the internal mesh
    for _ in range(retries):
        if post("/billing/events", event):
            return "ok"
    return "dead-letter"
